PromoPart::PromoPart() : tag_(Tag::kImage) {
  data_.image = new PromoImagePartPtr;
}

PromoPart::~PromoPart() {
  DestroyActive();
}


void PromoPart::set_image(
    PromoImagePartPtr image) {
  if (tag_ == Tag::kImage) {
    *(data_.image) = std::move(image);
  } else {
    DestroyActive();
    tag_ = Tag::kImage;
    data_.image = new PromoImagePartPtr(
        std::move(image));
  }
}
void PromoPart::set_link(
    PromoLinkPartPtr link) {
  if (tag_ == Tag::kLink) {
    *(data_.link) = std::move(link);
  } else {
    DestroyActive();
    tag_ = Tag::kLink;
    data_.link = new PromoLinkPartPtr(
        std::move(link));
  }
}
void PromoPart::set_text(
    PromoTextPartPtr text) {
  if (tag_ == Tag::kText) {
    *(data_.text) = std::move(text);
  } else {
    DestroyActive();
    tag_ = Tag::kText;
    data_.text = new PromoTextPartPtr(
        std::move(text));
  }
}

void PromoPart::DestroyActive() {
  switch (tag_) {

    case Tag::kImage:

      delete data_.image;
      break;
    case Tag::kLink:

      delete data_.link;
      break;
    case Tag::kText:

      delete data_.text;
      break;
  }
}

